using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public class ReverseContactTrace:MonoBehaviour {public static List<string> Rows=new();void OnCollisionEnter(Collision c){Rows.Add(c.collider.name+" speed="+c.relativeVelocity+" impulse="+c.impulse+" "+string.Join(";",c.contacts.Select(x=>x.point+" normal="+x.normal)));}}
public static class DiagnoseReverseContact {public static string Main(){EditorApplication.delayCall+=()=>{var mode=Physics.simulationMode;try{EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");Physics.simulationMode=SimulationMode.Script;var car=Object.FindAnyObjectByType<RaceDirector>().vehicle;typeof(VehicleSurfaceContacts).GetMethod("Reset",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,null);typeof(ArcadeVehicle).GetMethod("Awake",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(car,null);(car.GetComponent<VehicleConfiguration>()??car.gameObject.AddComponent<VehicleConfiguration>()).Apply("moto");car.gameObject.AddComponent<ReverseContactTrace>();var axis=new Vector3(1,0,.2f).normalized;var p=new Vector3(370,0,-6.9f);p.y=Racer.Editor.BackyardReverseAuthoring.Ground(p)+.6f;car.Body.position=p;car.Body.rotation=Quaternion.LookRotation(axis);car.transform.SetPositionAndRotation(p,car.Body.rotation);Physics.SyncTransforms();for(int n=0;n<60;n++){car.Simulate(0,0,0,.02f);Physics.Simulate(.02f);}car.Body.linearVelocity=(axis+Vector3.up*.21f).normalized*32;for(int n=0;n<100;n++){car.Simulate(.6f,0,0,.02f);Physics.Simulate(.02f);Physics.SyncTransforms();}File.WriteAllLines("Docs/BackyardReverseCorrections/lip-contact.txt",ReverseContactTrace.Rows);}catch(Exception e){File.WriteAllText("Docs/BackyardReverseCorrections/lip-contact-error.txt",e.ToString());}finally{Physics.simulationMode=mode;EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");}};return "One failing-lip collision diagnosis";}}

